import zeros = require( '@stdlib/ndarray/base/zeros' );
import scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
import gapx = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( 'generic', [ 3 ], 'row-major' );
	const alpha = scalar2ndarray( 5.0, { 'dtype': 'generic' } );
	gapx( [ x, alpha ] ); // $ExpectType ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object containing ndarrays...
{
	const alpha = scalar2ndarray( 5.0, { 'dtype': 'generic' } );
	gapx( 123 ); // $ExpectError
	gapx( true ); // $ExpectError
	gapx( false ); // $ExpectError
	gapx( null ); // $ExpectError
	gapx( undefined ); // $ExpectError
	gapx( '5' ); // $ExpectError
	gapx( [ '1', '2' ] ); // $ExpectError
	gapx( {} ); // $ExpectError
	gapx( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( 'generic', [ 3 ], 'row-major' );
	const alpha = scalar2ndarray( 5.0, { 'dtype': 'generic' } );
	gapx(); // $ExpectError
	gapx( [ x, alpha ], 10 ); // $ExpectError
}
